command:
$ErrorActionPreference="Stop"
$roots=@(
  "C:\dev\flyExplorer\out",
  "C:\dev\flyExplorer\logs\m27",
  "C:\actions-runner\flyExplorer\_work\_temp"
)
Write-Host "SHUTDOWN_DIAGNOSTIC_BUILD_OR_PACKAGE=NOT_RUN"
foreach($root in $roots){
  if(Test-Path -LiteralPath $root){
    Write-Host "ROOT_PRESENT=$root"
  }else{
    Write-Host "ROOT_MISSING=$root"
  }
}
$canonicalRelease="C:\dev\flyExplorer\out\winui\Release\flyExplorer.exe"
$canonicalSetup="C:\dev\flyExplorer\out\package\flyExplorer-Setup-x64.exe"
Write-Host "CANONICAL_RELEASE_PRESENT=$([bool](Test-Path -LiteralPath $canonicalRelease -PathType Leaf))"
Write-Host "CANONICAL_SETUP_PRESENT=$([bool](Test-Path -LiteralPath $canonicalSetup -PathType Leaf))"
$tempMatches=@()
$tempRoot="C:\actions-runner\flyExplorer\_work\_temp"
if(Test-Path -LiteralPath $tempRoot){
  $tempMatches=@(
    Get-ChildItem -LiteralPath $tempRoot -Directory -Filter "current-release-packaging-*" -ErrorAction SilentlyContinue |
      Select-Object -ExpandProperty FullName
  )
}
Write-Host "PACKAGING_TEMP_WORKTREES=$($tempMatches.Count)"
foreach($item in $tempMatches){Write-Host "PACKAGING_TEMP=$item"}
$installRoot="C:\dev\flyExplorer\logs\m27"
$installed=@()
if(Test-Path -LiteralPath $installRoot){
  $installed=@(
    Get-ChildItem -LiteralPath $installRoot -Directory -Filter "flyExplorer-installer-test-*" -ErrorAction SilentlyContinue |
      Select-Object -ExpandProperty FullName
  )
}
Write-Host "OWNED_INSTALL_ROOTS=$($installed.Count)"
foreach($item in $installed){Write-Host "OWNED_INSTALL_ROOT=$item"}
Get-Process flyExplorer -ErrorAction SilentlyContinue | ForEach-Object {
  Write-Host "LIVE_FLYEXPLORER_PID=$($_.Id)"
}
Write-Host "SHUTDOWN_DIAGNOSTIC_FILESYSTEM_PASS"
